-- 1354 sourced facts. CONTRACTS.md §1 invariants 2/3/5 are DEFERRED constraint
-- triggers, so these three statements must land in one transaction; seed.sql wraps them.
delete from public.sourced_facts;


-- ---------------------------------------------------------------------------
-- Seed users — all eleven roles, predictable ids
--
-- PASSWORDS ARE NOT COMMITTED. tasks/W1-A asks for eleven loggable-in accounts so W4-A
-- can exercise each role. The 1Çatı reference satisfies that with a plaintext literal in
-- its seed. That is safe there and NOT safe here: this repository is public and the
-- Supabase project is live on the internet, so a committed password would be a published
-- admin credential for a reachable database.
--
-- Instead the password is read from a session GUC and falls back to fresh random bytes.
-- The accounts and their ids are therefore always deterministic — which is what the RLS
-- tests actually need — while the credential is only known to whoever supplied it:
--
--     psql "$SUPABASE_DB_URL" -c "set azura.seed_password = '…'" -f supabase/seed.sql
--     PGOPTIONS="-c azura.seed_password=…" npx supabase db reset
--
-- Without the GUC the accounts exist and RLS tests pass; nobody can log in as them.
-- ---------------------------------------------------------------------------

do $$
declare
  v_password text := coalesce(
    nullif(current_setting('azura.seed_password', true), ''),
    encode(gen_random_bytes(24), 'base64')
  );
  v_company  uuid := '11111111-1111-4111-8111-111111111111';
  v_role     text;
  v_roles    text[] := array[
    'admin', 'manager', 'accountant', 'staff', 'owner', 'tenant',
    'guest', 'service_provider', 'child_owner', 'child_tenant', 'child_guest'
  ];
  v_idx      integer := 0;
  v_uid      uuid;
  v_email    text;
begin
  foreach v_role in array v_roles loop
    v_idx := v_idx + 1;
    v_uid := ('b0000000-0000-4000-8000-' || lpad(v_idx::text, 12, '0'))::uuid;
    v_email := v_role || '@azura.local';

      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      is_sso_user, is_anonymous
    )
    values (
      '00000000-0000-0000-0000-000000000000',
      v_uid,
      'authenticated',
      'authenticated',
      v_email,
      extensions.crypt(v_password, extensions.gen_salt('bf')),
      now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      -- No "role" key here, ever. public.handle_new_user() ignores client-supplied roles
      -- by design (migration 00); putting one in this object would suggest otherwise.
      jsonb_build_object('full_name', initcap(replace(v_role, '_', ' ')), 'locale', 'de'),
      now(), now(), false, false
    )
    on conflict (id) do update
      set email = excluded.email,
          encrypted_password = excluded.encrypted_password,
          email_confirmed_at = excluded.email_confirmed_at,
          raw_user_meta_data = excluded.raw_user_meta_data,
          updated_at = now();

    -- GoTrue's Go scanner cannot read NULL into its non-nullable string fields, so a
    -- directly-inserted auth user with NULL token columns breaks the login endpoint.
    update auth.users
       set confirmation_token         = coalesce(confirmation_token, ''),
           recovery_token             = coalesce(recovery_token, ''),
           email_change_token_new     = coalesce(email_change_token_new, ''),
           email_change               = coalesce(email_change, ''),
           email_change_token_current = coalesce(email_change_token_current, ''),
           phone_change               = coalesce(phone_change, ''),
           phone_change_token         = coalesce(phone_change_token, ''),
           reauthentication_token     = coalesce(reauthentication_token, ''),
           email_change_confirm_status = coalesce(email_change_confirm_status, 0)
     where id = v_uid;

      id, provider_id, user_id, identity_data, provider,
      last_sign_in_at, created_at, updated_at
    )
    values (
      ('c0000000-0000-4000-8000-' || lpad(v_idx::text, 12, '0'))::uuid,
      v_email,
      v_uid,
      jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true, 'phone_verified', false),
      'email',
      now(), now(), now()
    )
    on conflict (provider_id, provider) do update
      set user_id = excluded.user_id,
          identity_data = excluded.identity_data,
          updated_at = now();

    -- The signup trigger created the profile at role 'tenant' (correctly — it never
    -- honours a client-supplied role). Elevate it here, in the service context.
    update public.profiles
       set role = v_role::public.app_role,
           company_id = v_company,
           full_name = initcap(replace(v_role, '_', ' ')),
           email = v_email,
           is_active = true
     where id = v_uid;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Residency fixtures
--
-- Small and very deliberate. These exist so 04-rls-negative.sql has something real to
-- prove a denial against: two different owners each holding one NON-PUBLIC unit, plus a
-- tenant. Without a non-public unit the negative test is vacuous — every unit is in the
-- public sales catalogue, so "owner A cannot read owner B's unit" would be false for the
-- uninteresting reason that everyone can read everything.
-- ---------------------------------------------------------------------------

update public.units
   set is_publicly_listed = false
 where id in ('AZW-B01-0001', 'AZW-B01-0002', 'AZW-B01-0003');

   'b0000000-0000-4000-8000-000000000005', 'Owner One',  'owner@azura.local',  'de', 'individual'),
  ('d0000000-0000-4000-8000-000000000002', '11111111-1111-4111-8111-111111111111',
   null,                                    'Owner Two',  'owner2@azura.local', 'en', 'individual'),
  ('d0000000-0000-4000-8000-000000000003', '11111111-1111-4111-8111-111111111111',
   'b0000000-0000-4000-8000-000000000006', 'Tenant One', 'tenant@azura.local', 'tr', 'individual')
on conflict (id) do update
  set profile_id = excluded.profile_id,
      full_name  = excluded.full_name,
      email      = excluded.email;

   'd0000000-0000-4000-8000-000000000001', 'owner',  100, current_date - (365)::integer, true),
  ('e0000000-0000-4000-8000-000000000002', 'AZW-B01-0002',
   'd0000000-0000-4000-8000-000000000002', 'owner',  100, current_date - (300)::integer, true),
  ('e0000000-0000-4000-8000-000000000003', 'AZW-B01-0003',
   'd0000000-0000-4000-8000-000000000003', 'tenant', null, current_date - (120)::integer, true)
on conflict (id) do update
  set unit_id = excluded.unit_id, resident_id = excluded.resident_id;

-- child_owner shadows owner. current_user_scope_profile_id() resolves the child to this
-- guardian, so the child reaches exactly AZW-B01-0001 and nothing else — which is what
-- "a child role inherits a strict subset" has to mean to be testable.
   'b0000000-0000-4000-8000-000000000005',
   'b0000000-0000-4000-8000-000000000009', 'guardian', 'active', now()),
  ('f0000000-0000-4000-8000-000000000002',
   'b0000000-0000-4000-8000-000000000006',
   'b0000000-0000-4000-8000-000000000010', 'guardian', 'active', now())
on conflict (guardian_profile_id, child_profile_id) do update
  set status = excluded.status;

-- ---------------------------------------------------------------------------
-- Search projection
--
-- min_role_level 0 on units, because the public catalogue is genuinely public. The RPC
-- still refuses callers below staff, so this only widens what a permitted caller sees,
-- never who may call.
-- ---------------------------------------------------------------------------

delete from public.operational_search_documents;

select
  u.company_id,
  u.site_id,
  'units',
  u.id,
  u.id || ' · ' || u.layout::text,
  concat_ws(' · ',
    'Block ' || u.block_code,
    case when u.interior_m2 is not null then u.interior_m2::text || ' m²' end,
    case when u.asking_price_amount is not null
      then u.asking_price_amount::text || ' ' || u.asking_price_currency::text end,
    u.sale_status::text,
    u.data_quality::text
  ),
  'de',
  0,
  jsonb_build_object('layout', u.layout, 'dataQuality', u.data_quality, 'block', u.block_code)
from public.units u;

select
  s.company_id,
  s.id,
  'sites',
  s.code,
  s.name,
  concat_ws(', ', s.district, s.city, s.province, s.country),
  'de',
  0,
  jsonb_build_object('code', s.code)
from public.sites s;

-- ---------------------------------------------------------------------------
-- Drop the service identity again.
-- ---------------------------------------------------------------------------

select set_config('request.jwt.claims', '', true);

commit;
